<script setup>
import { computed, onMounted, ref } from 'vue';
import { X, Pencil, Images, Check, UserRound, ArrowRight } from 'lucide-vue-next';
import UiButton from './UiButton.vue';
import UiBadge from './UiBadge.vue';
import UiDialog from './UiDialog.vue';
import RoomArt from './RoomArt.vue';
import { loadLabellers, api } from '../api/annotate.js';
const props=defineProps({batch:Object,state:Object});
const emit=defineEmits(['close','edit','choices','changed','message']);
const tab=ref('Unannotated');const sort=ref('Newest');const modal=ref('');const draft=ref('');const notice=ref('');
// Live: a real assignment (api/annotate.js). What this person may do comes from the backend (``batch.may``).
const live=computed(()=>!!props.state.live);const may=computed(()=>props.batch.may||{});const busy=ref(false);
const images=computed(()=>props.state.images.filter(i=>i.batchId===props.batch.id));
const labeled=i=>live.value?!!i.labelled:(i.shapes.length>0||i.noObjects);
const count=computed(()=>images.value.filter(labeled).length);
const shown=computed(()=>{let list=images.value.filter(i=>tab.value==='Annotated'?labeled(i):!labeled(i));return sort.value==='Name A–Z'?[...list].sort((a,b)=>a.name.localeCompare(b.name)):sort.value==='Newest'?[...list].reverse():list;});
const people=computed(()=>(props.state.labellers||[]));
onMounted(()=>{if(live.value&&may.value.reassign)loadLabellers(props.state).catch(()=>{});});
function edit(name){modal.value=name;draft.value=name==='Instructions'?props.batch.instructions||'':name==='Assignment'?(live.value?(props.batch.labeller?.id??''):props.batch.assignee):(live.value?(props.batch.givenName||props.batch.name):props.batch.name);}
async function act(action,body={}){busy.value=true;notice.value='';try{await api.assignmentAction(props.state.ref,props.batch.number,action,body);modal.value='';emit('changed');}catch(e){notice.value=e.message;}finally{busy.value=false;}}
async function save(){
  if(live.value){if(modal.value==='Submit for review')return act('return',draft.value.trim()?{note:draft.value.trim()}:{});if(modal.value==='Assignment'){if(!draft.value){notice.value='Choose who labels it now.';return;}return act('reassign',{labeller:draft.value});}
    if(['Send back','Reject'].includes(modal.value)){if(!draft.value.trim()){notice.value='Write the reason first.';return;}return act(modal.value==='Reject'?'reject':'send-back',{reason:draft.value.trim()});}
    if(modal.value!=='Instructions'&&!draft.value.trim())return;busy.value=true;try{await api.updateAssignment(props.state.ref,props.batch.number,modal.value==='Instructions'?{instructions:draft.value}:{name:draft.value.trim()});modal.value='';emit('changed');}catch(e){notice.value=e.message;}finally{busy.value=false;}return;}
  if(modal.value!=='Instructions'&&!draft.value.trim())return;const field={Instructions:'instructions',Assignment:'assignee','Rename job':'name'}[modal.value];props.batch[field]=draft.value.trim();props.batch.timeline??=[];props.batch.timeline.unshift({text:`${modal.value} updated locally`,time:new Date().toLocaleString()});modal.value='';}
function submit(){if(count.value!==images.value.length||!images.value.length){notice.value='Label every image or mark it as having no objects before submitting.';return;}
  if(live.value){if(!may.value.return){notice.value=props.batch.mine?'This assignment is not with you to return now.':'Only its labeller submits it for review.';return;}draft.value='';modal.value='Submit for review';return;}
  images.value.filter(i=>i.state!=='Accepted').forEach(i=>i.state='In review');props.batch.status='In review';props.batch.timeline??=[];props.batch.timeline.unshift({text:'Submitted for review locally',time:new Date().toLocaleString()});notice.value='Submitted to the local review queue. No backend request was sent.';}
</script>
<template>
 <section class="annotation-job">
  <header class="job-header"><span v-if="batch.code" class="batch-code" title="Reference code of this batch">{{batch.code}}</span><h2>{{batch.name}}</h2><button v-if="!live||may.edit" class="icon-button" aria-label="Rename job" @click="edit('Rename job')"><Pencil :size="15"/></button><div class="job-actions"><UiButton :disabled="!images.length" @click="emit('edit',images.find(i=>!labeled(i))||images[0])"><Images :size="16"/>Continue Annotating</UiButton><UiButton v-if="!live||may.return" :disabled="busy" @click="submit">Submit for Review</UiButton><template v-if="live&&may.review"><UiButton variant="primary" :disabled="busy" @click="act('accept')"><Check :size="16"/>Accept all</UiButton><UiButton :disabled="busy" @click="modal='Send back';draft=''">Send back</UiButton></template><UiButton v-if="live&&may.reject" :disabled="busy" @click="modal='Reject';draft=''">Reject</UiButton><button class="icon-button" aria-label="Close annotation job" @click="emit('close')"><X :size="20"/></button></div></header>
  <p v-if="notice" role="status" class="job-notice">{{notice}}</p><div v-if="live&&batch.sentBack" class="job-callout sent-back" role="note"><strong>Sent back to you</strong><p>{{batch.sentBack}}</p><small>Fix what it names, then press Submit for Review again.</small></div><div v-else-if="live&&batch.returnNote&&batch.status==='In review'" class="job-callout" role="note"><strong>Note from {{batch.labeller?.name||'the labeller'}}</strong><p>{{batch.returnNote}}</p></div>
  <div class="job-layout"><aside class="job-sidebar">
   <div class="job-section"><div class="job-section-title"><h3>Progress</h3><small>{{images.length}} media items</small></div><progress :value="count" :max="images.length||1" aria-label="Annotation progress"/><div class="progress-key"><span><Check :size="12"/>{{count}} annotated</span><span>{{images.length-count}} remaining</span></div></div>
   <div class="job-section"><div class="job-section-title"><h3>Instructions</h3><button v-if="!live||may.edit" @click="edit('Instructions')"><Pencil :size="13"/>Edit</button></div><p class="job-instructions">{{batch.instructions||'No specific instructions were added when this job was assigned.'}}</p></div>
   <div class="job-section"><div class="job-section-title"><h3>Assignment</h3><button v-if="!live||may.reassign" @click="edit('Assignment')"><Pencil :size="13"/>Reassign</button></div><div class="job-person"><span><UserRound :size="18"/></span><div>{{batch.assignee}}<small>{{live?'Labeller':'Labeler · local preview'}}</small></div></div></div>
   <div class="job-section"><h3>Timeline</h3><ol class="job-timeline"><li v-for="(event,i) in batch.timeline||[]" :key="i"><span>{{event.text}}</span><small>{{event.time}}</small></li><li v-if="!live"><span>Sample job available in this browser session.</span><small>Prototype data</small></li></ol></div>
   <UiButton v-if="!live" @click="emit('choices')">Labeling choices<ArrowRight :size="14"/></UiButton>
  </aside><div class="job-gallery"><div class="job-gallery-toolbar"><div class="job-tabs"><button v-for="name in ['Unannotated','Annotated']" :key="name" :aria-pressed="tab===name" @click="tab=name">{{name}}<UiBadge>{{name==='Annotated'?count:images.length-count}}</UiBadge></button></div><select v-model="sort" aria-label="Sort job images"><option>Newest</option><option>Oldest</option><option>Name A–Z</option></select></div><div class="job-images"><button v-for="image in shown" :key="image.id" @click="emit('edit',image)" :aria-label="`Annotate ${image.name}`"><span class="job-thumbnail"><RoomArt v-if="image.sample" :variant="image.variant||0"/><img v-else :src="image.url" :alt="image.name"/></span><span class="job-filename" :title="image.name">{{image.name}}</span></button></div><div v-if="!shown.length" class="job-empty"><Images :size="30"/><h3>No {{tab.toLowerCase()}} images</h3><p>{{tab==='Annotated'?'Save labels in the editor to see them here.':'All images in this job have labels.'}}</p></div></div></div>
 </section>
 <UiDialog :open="!!modal" :title="modal" @close="modal=''"><label class="field-label">{{modal}}<textarea v-if="['Instructions','Send back','Reject','Submit for review'].includes(modal)" v-model="draft" class="text-input" rows="5" maxlength="1000" :aria-label="modal==='Submit for review'?'Note for the approver':modal" :placeholder="modal==='Instructions'?'':modal==='Submit for review'?'A note for the person who approves (optional): what to check, what was unclear.':'Why? The labeller reads this.'"/><select v-else-if="modal==='Assignment'&&live" v-model="draft" class="text-input"><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}{{p.you?' (you)':''}} · {{p.role_label}}</option></select><select v-else-if="modal==='Assignment'" v-model="draft" class="text-input"><option>Me</option><option>Demo labeller</option><option>Demo reviewer</option></select><input v-else v-model="draft" class="text-input" maxlength="100"/></label><p v-if="!live" class="dialog-description">Saved only in this prototype. No notifications are sent.</p><p v-else-if="modal==='Reject'" class="dialog-description">Its photos can go into a new batch afterwards.</p><p v-if="notice&&modal" class="field-error" role="alert">{{notice}}</p><div class="dialog-actions"><UiButton @click="modal=''">Cancel</UiButton><UiButton variant="primary" :disabled="busy" @click="save">{{live?(modal==='Send back'?'Send back':modal==='Reject'?'Reject':modal==='Submit for review'?'Submit':'Save'):'Save locally'}}</UiButton></div></UiDialog>
</template>
<style scoped>
.job-callout{margin:12px 20px 0;padding:12px 14px;border-radius:8px;background:#eff6ff;border:1px solid #bfdbfe;font-size:13px}.job-callout strong{display:block;color:#1d4ed8;margin-bottom:4px}.job-callout p{margin:0;color:#16213a;white-space:pre-wrap}.job-callout small{display:block;margin-top:6px;color:#6d7c92}.job-callout.sent-back{background:#fffbeb;border-color:#fde68a}.job-callout.sent-back strong{color:#b45309}
.annotation-job{border:1px solid #e1e4eb;background:white;border-radius:8px;overflow:hidden}.job-header{display:flex;align-items:center;gap:10px;padding:20px 24px;border-bottom:1px solid #e0e3eb;background:#f9fafb}.job-header h2{font-size:19px;font-weight:500}.job-actions{margin-left:auto;display:flex;gap:9px;align-items:center}.job-layout{display:grid;grid-template-columns:285px minmax(0,1fr);min-height:640px}.job-sidebar{border-right:1px solid #e1e4eb;padding:26px 24px}.job-section{margin-bottom:30px}.job-section h3{font-size:15px;font-weight:500}.job-section-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:16px}.job-section-title small{font-size:11px}.job-section-title button{border:0;background:none;display:flex;align-items:center;gap:4px;color:var(--aadml-primary);font-size:12px}.job-sidebar progress{width:100%;height:8px;border:0;border-radius:6px;overflow:hidden;background:#d8dce3}.job-sidebar progress::-webkit-progress-bar{background:#d8dce3}.job-sidebar progress::-webkit-progress-value{background:var(--aadml-focus)}.progress-key{display:flex;gap:14px;font-size:11px;color:#8290a1;margin-top:6px}.progress-key span{display:flex;gap:4px}.progress-key span:first-child{color:var(--aadml-primary)}.job-instructions{font-size:12px;border-left:1px solid #d6dce6;padding-left:12px;white-space:pre-wrap}.job-person{display:flex;align-items:center;gap:10px;font-size:13px}.job-person>span{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:#005f50;color:white}.job-person small{display:block;color:#8390a0;font-size:11px;margin-top:4px}.job-timeline{list-style:none;padding:0 0 0 14px;margin-top:20px;border-left:1px solid #e0e4eb}.job-timeline li{font-size:12px;color:#63748c;margin:0 0 22px;position:relative}.job-timeline li:before{content:'';position:absolute;left:-19px;top:4px;width:9px;height:9px;background:#006050;border-radius:50%}.job-timeline small{display:block;font-size:10px;margin-top:6px}.job-gallery-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #e0e3eb;padding:12px 22px}.job-tabs{display:flex;gap:14px}.job-tabs button{display:flex;gap:7px;align-items:center;border:0;border-bottom:2px solid transparent;background:none;color:#65778f;padding:10px 6px}.job-tabs button[aria-pressed=true]{color:var(--aadml-primary);border-color:var(--aadml-primary)}.job-gallery select{background:white;border:1px solid #d3d9e3;border-radius:6px;padding:9px;color:#63748c;font-size:12px}.job-images{display:grid;grid-template-columns:repeat(auto-fill,minmax(155px,1fr));gap:24px;padding:42px 24px}.job-images button{padding:0;border:0;background:none;text-align:left;min-width:0}.job-thumbnail{display:block;border:2px solid transparent;border-radius:7px;overflow:hidden;height:115px;background:#f3f4f7}.job-images button:hover .job-thumbnail{border-color:var(--aadml-focus);box-shadow:0 2px 8px #2563eb33}.job-thumbnail img,.job-thumbnail svg{width:100%;height:100%;object-fit:cover}.job-filename{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#536b89;font-size:12px;margin-top:7px}.job-empty{text-align:center;padding:60px 20px;color:#8b91a0}.job-empty h3{margin:12px}.job-empty p{font-size:13px}.job-notice{padding:12px 24px;background:var(--aadml-tint);font-size:13px}@media(max-width:900px){.job-layout{grid-template-columns:220px minmax(0,1fr)}.job-header{flex-wrap:wrap}.job-actions{margin-left:0}}@media(max-width:650px){.job-layout{grid-template-columns:1fr}.job-sidebar{border-right:0;border-bottom:1px solid #ddd}.job-section{margin-bottom:20px}.job-gallery-toolbar{flex-wrap:wrap}.job-images{padding:20px;grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
